/** Real taskbar geometry, shell controls, desktop guidance, external cards and title-bar shake. */
public final class TenInteractionSmoke extends TenThemeSmoke {
 @Override public void onStart(){Bundle result=new Bundle();try{
  store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putBoolean("taskbar_static",true).remove("ten_v13_taskbar_defaults").remove(TenDesktops.KEY).remove(TenDesktopItems.KEY).commit();TenThemes.TEN.get(0).apply(store);
  getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
  home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.description(root,"Start menu")!=null,"Desktop ready");
  check(!store.prefs.getBoolean("taskbar_static",true),"Upgrade adopts scrollable Ten taskbar");
  taskbar();controls();desktopGuide();externalCards();shake();
  result.putString("stream","PASS: scrollable upgrade default and later static preference; one fixed Nota slot independent of scroll/reorder in both orientations; all 17 device-control themes and opposite app modes; real control navigation/volume; Nota-created desktop opens interactive Task View with italic guidance and return action; installed-app icon card actually launches its app; physical title-bar shake hides/restores other windows, restores previously minimized windows and leaves restored controls interactive.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{shot("ten13-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
 void taskbar()throws Exception{
  ui(()->{store.quickLaunch(Arrays.asList("@nota","@browser","@files","@notes","@calendar","@photos","@settings","@weather","@clock","@taskmanager","@recycle","@gadget:calculator"));home.applyTenAppearance();});
  for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE}){
   boolean portrait=orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT;ui(()->home.setRequestedOrientation(orientation));await(()->portrait?root.getHeight()>root.getWidth():root.getWidth()>root.getHeight(),"Taskbar orientation");
   int[] before=new int[2];ui(()->{View nota=fixedNota();nota.getLocationOnScreen(before);HorizontalScrollView strip=(HorizontalScrollView)root.findViewWithTag("taskbar-items");check(!descendant(strip,nota),"Nota outside scroll container");strip.scrollTo(10000,0);});await(()->((HorizontalScrollView)root.findViewWithTag("taskbar-items")).getScrollX()>0,"App buttons genuinely scroll");
   ui(()->{int[] after=new int[2];fixedNota().getLocationOnScreen(after);check(Arrays.equals(before,after),"Nota stays fixed after horizontal scroll");check(countNota(TenSmoke.description(root,"Desktop taskbar"))==1,"One Nota button");fixedNota().performClick();check(windows().containsKey("@nota"),"Fixed Nota button opens assistant");});shot("ten13-fixed-nota-"+(portrait?"portrait":"landscape"));
  }
  ui(()->store.prefs.edit().putBoolean("taskbar_static",true).commit());ActivityMonitor monitor=new ActivityMonitor(MainActivity.class.getName(),null,false);addMonitor(monitor);ui(home::recreate);Activity next=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);check(next instanceof MainActivity,"Desktop recreated");home=(MainActivity)next;root=home.getWindow().getDecorView();check(store.prefs.getBoolean("taskbar_static",false),"Later user static choice survives recreation");ui(()->{store.prefs.edit().putBoolean("taskbar_static",false).commit();home.applyTenAppearance();});
 }
 void controls()throws Exception{
  List<TenThemes.Preset> themes=new ArrayList<>(TenThemes.TEN);themes.addAll(TenThemes.AERO);
  for(TenThemes.Preset theme:themes){ui(()->{theme.apply(store);store.prefs.edit().putBoolean("ten_apps_dark",!theme.appsDark()).commit();home.applyTenAppearance();TenSmoke.description(root,"Device controls").performClick();View panel=TenSmoke.description(root,"Ten device controls");check(panel!=null,"Controls open for "+theme.name);View body=(View)TenSmoke.description(panel,"Tray status details").getParent();check(body.getBackground() instanceof ColorDrawable&&((ColorDrawable)body.getBackground()).getColor()==TenStyle.surface(home),"Controls follow shell surface, independent of app mode");TextView summary=(TextView)TenSmoke.description(panel,"Tray status details");check(TenAccent.contrast(summary.getCurrentTextColor(),TenStyle.surface(home))>=4.5,"Summary readable: "+theme.name);for(String name:new String[]{"Task Manager","Battery status","Network status","Bluetooth","Volume control","Brightness control","Clock and calendar","All settings"})check(TenSmoke.description(panel,name)!=null,"Functional tile: "+name);});}
  shot("ten13-controls-aero");ui(()->{TenThemes.TEN.get(1).apply(store);home.applyTenAppearance();TenSmoke.description(root,"Device controls").performClick();});shot("ten13-controls-light");
  ui(()->TenSmoke.description(TenSmoke.description(root,"Ten device controls"),"Volume control").performClick());await(()->TenSmoke.description(root,"Media volume") instanceof SeekBar,"Volume tile opens real slider");ui(()->{SeekBar slider=(SeekBar)TenSmoke.description(root,"Media volume");check(slider.getMax()==home.getSystemService(android.media.AudioManager.class).getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC),"Volume uses actual Android scale");TenSmoke.description(root,"Close tray flyout").performClick();TenThemes.TEN.get(0).apply(store);home.applyTenAppearance();});
 }
 void desktopGuide()throws Exception{
  String[] previous={""};ui(()->{previous[0]=desks().current();home.open("@notes");((EditText)TenSmoke.description(windows().get("@notes"),"Notepad text")).setText("Keep this desktop note");home.open("@nota");TenNotaPanel nota=(TenNotaPanel)windows().get("@nota").body;nota.task.setSelection(0);nota.input.setText("Create a new virtual desktop");nota.send.performClick();});await(()->TenSmoke.description(root,"Create new desktop")!=null,"Nota exposes explicit new-desktop action");ui(()->TenSmoke.description(root,"Create new desktop").performClick());await(()->TenSmoke.description(root,"New virtual desktop guidance")!=null,"New desktop immediately explains Task View");ui(()->{check(!desks().current().equals(previous[0]),"New desktop selected");View guide=TenSmoke.description(root,"New virtual desktop guidance");check(hasItalic(guide),"Suggestion uses italic text");check(TenSmoke.description(root,"Switch desktop Desktop 1")!=null,"Previous desktop visible above guide");});shot("ten13-new-desktop-guide");ui(()->TenSmoke.description(root,"Return to previous desktop").performClick());await(()->desks().current().equals(previous[0]),"Return button restores original desktop");ui(()->check(((EditText)TenSmoke.description(windows().get("@notes"),"Notepad text")).getText().toString().equals("Keep this desktop note"),"Old desktop contents retained"));
 }
 void externalCards()throws Exception{
  String id="com.nthexperience.desktop.fixture/com.nthexperience.desktop.fixture.TaskActivity";ui(()->{ExternalTasks.opened(id);home.open("@taskview");});await(()->TenSmoke.description(root,"Switch to Android app Task switch probe")!=null,"Installed app card visible");ui(()->{View card=TenSmoke.description(root,"Switch to Android app Task switch probe");ImageView icon=(ImageView)TenSmoke.description(card,"App icon: Task switch probe");check(icon!=null&&icon.getDrawable()!=null,"Card uses actual PackageManager icon");check(TenSmoke.text(card,"Tap to return to app")!=null&&TenSmoke.text(card,"Android app\nOpen in Android")==null,"Clear visual app card replaces generic placeholder");});shot("ten13-android-app-card");ui(()->TenSmoke.description(root,"Switch to Android app Task switch probe").performClick());awaitSystem("Task probe note");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);await(home::hasWindowFocus,"Return from external app");
 }
 void shake()throws Exception{
  ui(()->{for(DesktopWindow window:new ArrayList<>(windows().values()))window.closeWindow();home.open("@notes");home.open("@calendar");home.open("@gadget:calculator");});await(()->windows().get("@notes").getWidth()>0,"Shake windows laid out");
  ui(()->{windows().get("@calendar").minimize();windows().get("@gadget:calculator").minimize();windows().get("@notes").restore();});gesture();await(()->windows().get("@calendar").isShown()&&windows().get("@gadget:calculator").isShown(),"Shake restores windows minimized before any shake");
  gesture();await(()->!windows().get("@calendar").isShown()&&!windows().get("@gadget:calculator").isShown(),"Next shake hides all other built-in windows");gesture();await(()->windows().get("@calendar").isShown()&&windows().get("@gadget:calculator").isShown(),"Next shake restores all other windows");
  ui(()->{EditText editor=(EditText)TenSmoke.description(windows().get("@notes"),"Notepad text");editor.setText("Still interactive after shake");check(editor.isEnabled()&&windows().get("@calendar").getAlpha()==1&&windows().get("@gadget:calculator").getScaleX()==1,"Restored windows remain interactive and unscaled");});shot("ten13-shake-restored");
 }
 void gesture()throws Exception{
  ui(()->windows().get("@notes").restore());await(()->TenSmoke.description(root,"Notepad. Drag to move window.")!=null,"Caption visible");View caption=TenSmoke.description(root,"Notepad. Drag to move window.");int[] p=new int[2];ui(()->caption.getLocationOnScreen(p));float x=p[0]+caption.getWidth()/2f,y=p[1]+caption.getHeight()/2f,d=Aero.dp(home,36);long down=SystemClock.uptimeMillis();inject(down,MotionEvent.ACTION_DOWN,x,y);for(int n=0;n<4;n++){Thread.sleep(180);inject(down,MotionEvent.ACTION_MOVE,x+(n%2==0?d:-d),y+Aero.dp(home,n%2==0?12:-12));}inject(down,MotionEvent.ACTION_UP,x-d,y);SystemClock.sleep(250);
 }
 void inject(long down,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);getUiAutomation().injectInputEvent(event,true);event.recycle();}
 View fixedNota(){View bar=TenSmoke.description(root,"Desktop taskbar");for(int i=0;i<((ViewGroup)bar).getChildCount();i++){View child=((ViewGroup)bar).getChildAt(i);if("@nota".equals(child.getTag(R.id.taskbar_order_key)))return child;}throw new AssertionError("Fixed Nota slot missing");}
 int countNota(View view){int n="@nota".equals(view.getTag(R.id.taskbar_order_key))?1:0;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)n+=countNota(((ViewGroup)view).getChildAt(i));return n;}
 boolean descendant(View root,View target){if(root==target)return true;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++)if(descendant(((ViewGroup)root).getChildAt(i),target))return true;return false;}
 boolean hasItalic(View view){if(view instanceof TextView&&((((TextView)view).getTypeface().getStyle()&Typeface.ITALIC)!=0))return true;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)if(hasItalic(((ViewGroup)view).getChildAt(i)))return true;return false;}
 TenDesktops desks(){try{Field field=MainActivity.class.getDeclaredField("tenDesktops");field.setAccessible(true);return(TenDesktops)field.get(home);}catch(Exception e){throw new RuntimeException(e);}}
}
